+    let blocker = cube(
+        Point3::new(-30.0, y0, 0.0),
+        Point3::new(30.0, 40.0, 24.0),
+    );
+    let mut facets = wall.facets.to_vec();
+    facets.extend(blocker.facets.iter().copied());
+    facets
+}
